    { q: "Which Folic is correct about Folic acid?", opts: ["High in goat milk", "Presentation at early months", "All deficiency of folic acid are acquired", "Only animal sources are adequate"], correct: 2, reason: "Folic acid deficiency is generally acquired.", ref: "MID Anemia", diff: "M" }
